import { randomBytes } from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import { readIfExists } from './fs.js';

/** Variables that get a specific kind of random value. */
const SECRET_GENERATORS: Record<string, () => string> = {
  // Hex keeps the password safe to embed in connection URLs.
  DB_PASSWORD: () => randomBytes(24).toString('hex'),
  JWT_SECRET: () => randomBytes(48).toString('base64url')
};

/** Placeholder value of .env.example entries that must be replaced. */
export const PLACEHOLDER = 'change-me';

/** Variables holding secrets: generated by `qn create` and `qn env --generate-secrets`. */
export const isSecretKey = (key: string) =>
  key in SECRET_GENERATORS || /(?:^|_)(?:SECRET|PASSWORD|TOKEN|API_KEY|PRIVATE_KEY)$/.test(key);

/** A new random value for a secret variable. */
export const generateSecret = (key: string) => (SECRET_GENERATORS[key] ?? (() => randomBytes(32).toString('base64url')))();

/** `KEY=value` (optionally `export KEY=value`); a trailing \r of CRLF files is left out of the value. */
const ENV_LINE = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=(.*?)\r?$/;

/** The value of an env line without surrounding spaces or matching quotes. */
const unquote = (raw: string) => raw.trim().replace(/^(['"])(.*)\1$/, '$2');

/** The same env line with a new value (an `export ` prefix and the spacing before = are kept). */
const withValue = (line: string, value: string) => `${line.slice(0, line.indexOf('=') + 1)}${value}`;

/** Line ending of a file: CRLF when it has any, so edits keep the file's own style. */
const lineEnding = (content: string) => (content.includes('\r\n') ? '\r\n' : '\n');

/**
 * Fills the secret variables of an `.env.example` content with random values.
 * Other lines are kept as they are.
 */
export function fillSecrets(exampleContent: string): string {
  const eol = lineEnding(exampleContent);
  return exampleContent
    .split(/\r?\n/)
    .map((line) => {
      const key = ENV_LINE.exec(line)?.[1];
      return key && isSecretKey(key) ? withValue(line, generateSecret(key)) : line;
    })
    .join(eol);
}

export const ENV_FILE = '.env';
export const ENV_EXAMPLE_FILE = '.env.example';
/** .env holds secrets: readable by the owner only. */
export const ENV_FILE_MODE = 0o600;

/** KEY=value pairs of a dotenv file, in order (comments and blank lines ignored). */
export function parseEnv(content: string): Map<string, string> {
  const entries = new Map<string, string>();
  for (const line of content.split(/\r?\n/)) {
    const match = ENV_LINE.exec(line);
    if (match) entries.set(match[1], unquote(match[2]));
  }
  return entries;
}

/** A value that still has to be replaced: the placeholder, or an empty secret. */
export const isPlaceholder = (key: string, value: string) => value === PLACEHOLDER || (value === '' && isSecretKey(key));

/** How .env differs from .env.example, by variable name only: values are never part of it. */
export interface EnvComparison {
  /** In .env.example but not in .env. */
  missing: string[];
  /** In .env but not in .env.example. */
  extra: string[];
  /** In .env with a placeholder (or an empty secret). */
  placeholders: string[];
}

export function compareEnv(env: string, example: string): EnvComparison {
  const values = parseEnv(env);
  const expected = parseEnv(example);
  return {
    missing: [...expected.keys()].filter((key) => !values.has(key)),
    extra: [...values.keys()].filter((key) => !expected.has(key)),
    placeholders: [...values].filter(([key, value]) => isPlaceholder(key, value)).map(([key]) => key)
  };
}

export interface SecretsUpdate {
  content: string;
  /** Variables that got a random value. */
  generated: string[];
  /** Variables copied from .env.example with their example value. */
  added: string[];
}

/**
 * Completes an existing .env from .env.example: missing variables are
 * appended (secrets with random values) and secrets holding a placeholder
 * get one. With `rotate`, every secret gets a new value. Other lines,
 * comments included, are kept as they are.
 */
export function completeEnv(env: string, example: string, rotate = false): SecretsUpdate {
  const generated: string[] = [];
  const added: string[] = [];
  const eol = lineEnding(env);
  const lines = env.split(/\r?\n/).map((line) => {
    const match = ENV_LINE.exec(line);
    if (!match || !isSecretKey(match[1])) return line;
    if (!rotate && !isPlaceholder(match[1], unquote(match[2]))) return line;
    generated.push(match[1]);
    return withValue(line, generateSecret(match[1]));
  });

  const present = parseEnv(env);
  const appended: string[] = [];
  for (const [key, value] of parseEnv(example)) {
    if (present.has(key)) continue;
    if (isSecretKey(key)) {
      generated.push(key);
      appended.push(`${key}=${generateSecret(key)}`);
    } else {
      added.push(key);
      appended.push(`${key}=${value}`);
    }
  }

  let content = lines.join(eol);
  if (appended.length > 0) {
    const block = [`# Added by qn env from ${ENV_EXAMPLE_FILE}`, ...appended].join(eol);
    content = `${content.replace(/(\r?\n)*$/, eol)}${eol}${block}${eol}`;
  }
  return { content, generated, added };
}

/** Whether a project with these files gets a generated `.env` (see createEnvFile). */
export function generatesEnvFile(projectFiles: string[]): boolean {
  return projectFiles.includes(ENV_EXAMPLE_FILE);
}

/**
 * Creates `<projectDir>/.env` from `.env.example` with freshly generated
 * secrets. Returns false (and writes nothing) when there is no `.env.example`.
 */
export async function createEnvFile(projectDir: string): Promise<boolean> {
  const example = await readIfExists(path.join(projectDir, ENV_EXAMPLE_FILE));
  if (example === undefined) return false;

  await fs.writeFile(path.join(projectDir, ENV_FILE), fillSecrets(example), { mode: ENV_FILE_MODE });
  return true;
}
